const body = $json.body || $json;
const asin = String(body.asin || '').trim();
if (!asin || asin.length !== 10) {
  throw new Error('ASIN invalido');
}

const domain = String(body.domain || 'com').trim();
const slug = String(body.slug || '').trim();
const affiliateTag = String(body.affiliateTag || '').trim();
const keyword = String(body.keyword || '').trim();

const productUrl = slug
  ? `https://www.amazon.${domain}/${slug}/dp/${asin}`
  : `https://www.amazon.${domain}/dp/${asin}`;

const cookieParts = [];
if ($env.AMAZON_SESSION_ID && $env.AMAZON_UBID_MAIN) {
  cookieParts.push(`session-id=${$env.AMAZON_SESSION_ID}`);
  cookieParts.push(`ubid-main=${$env.AMAZON_UBID_MAIN}`);
}
if ($env.AMAZON_LC_COOKIE_NAME && $env.AMAZON_LC_COOKIE_VALUE) {
  cookieParts.push(`${$env.AMAZON_LC_COOKIE_NAME}=${$env.AMAZON_LC_COOKIE_VALUE}`);
}

return [{
  json: {
    asin, domain, slug, keyword, affiliateTag, productUrl,
    cookieHeader: cookieParts.join('; '),
    minDelayMs: Math.max(1000, Number(body.minDelayMs || 2500)),
    maxDelayMs: Math.max(1000, Number(body.maxDelayMs || 6000))
  }
}];

const html = String($json.body || '');
const req = $items('Normalize Request', 0, 0)[0].json;

if (!html || html.length < 1000) {
  throw new Error('HTML de produto vazio ou invalido');
}

const hasCaptcha = /validateCaptcha|errors\/validateCaptcha|/captcha//i.test(html);

const extract = (regex) => {
  const m = html.match(regex);
  return m && m[1] ? String(m[1]).replace(/\s+/g, ' ').trim() : '';
};

const decode = (s) => String(s || '')
  .replace(/&amp;/g, '&')
  .replace(/&quot;/g, String.fromCharCode(34))
  .replace(/&#39;/g, String.fromCharCode(39))
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>');

let title = extract(/id=\"productTitle\"[^>]*>([\s\S]*?)<\/span>/i);
if (!title) title = extract(/<meta property=\"og:title\" content=\"([^\"]+)\"/i);

let price = extract(/id=\"priceblock_dealprice\"[^>]*>([\s\S]*?)<\/span>/i)
  || extract(/id=\"priceblock_ourprice\"[^>]*>([\s\S]*?)<\/span>/i)
  || extract(/id=\"priceblock_saleprice\"[^>]*>([\s\S]*?)<\/span>/i)
  || extract(/id=\"price_inside_buybox\"[^>]*>([\s\S]*?)<\/span>/i)
  || extract(/data-a-color=\"price\"[^>]*><span class=\"a-offscreen\">([\s\S]*?)<\/span>/i);

price = decode(price).replace(/\s+/g, ' ').trim();

let oldPrice = extract(/priceBlockStrikePriceString[^>]*>([\s\S]*?)<\/span>/i)
  || extract(/data-a-strike=\"true\"[\s\S]*?<span class=\"a-offscreen\">([\s\S]*?)<\/span>/i);
oldPrice = decode(oldPrice).replace(/\s+/g, ' ').trim();

const rating = extract(/a-icon-alt\">([0-9][0-9.,]*)\s*out\s*of\s*5/i)
  || extract(/a-star-([0-9]-[0-9])/i).replace('-', '.');

let image = extract(/<meta property=\"og:image\" content=\"([^\"]+)\"/i);
if (!image) {
  image = extract(/\"hiRes\"\s*:\s*\"([^\"]+)\"/i) || extract(/\"large\"\s*:\s*\"([^\"]+)\"/i);
}
image = decode(image);

const brandRaw = extract(/po-brand[\s\S]*?po-break-word\">([\s\S]*?)<\/span>/i);
const brand = decode(brandRaw).trim();

const outOfStock = /id=\"outOfStock\"|Currently unavailable|temporarily out of stock/i.test(html);

const itemLink = `https://www.amazon.${req.domain}/dp/${req.asin}`;
const affiliateLink = req.affiliateTag
  ? `${itemLink}?tag=${encodeURIComponent(req.affiliateTag)}`
  : itemLink;

const payload = {
  marketplace: 'amazon',
  asin: req.asin,
  keyword: req.keyword,
  domain: req.domain,
  title: decode(title),
  price,
  oldPrice,
  rating: rating || '',
  image,
  brand,
  outOfStock,
  hasCaptcha,
  productUrl: itemLink,
  affiliateUrl: affiliateLink,
  scrapedAt: new Date().toISOString(),
  source: 'n8n-amazon-enrichment'
};

return [{ json: payload }];
